import os
import base64

B64_DATA = ""

def main():
    os.makedirs('data', exist_ok=True)
    target = os.path.join('data', 'accounts.json')
    if os.path.exists(target) and os.path.getsize(target) > 100:
        print(f"Account file already exists ({os.path.getsize(target)} bytes), skipping overwrite.")
        return
    with open(target, 'wb') as f:
        f.write(base64.b64decode(B64_DATA))
    print(f"Successfully restored {target} ({os.path.getsize(target)} bytes)!")

if __name__ == '__main__':
    main()
